DO $amie$ DECLARE changed integer; BEGIN
 WITH input AS (SELECT * FROM jsonb_to_recordset('[{"entity":"topic","id":"ptt_sol_dd_validation","source_hash":"35114f2abf86c9eebc7ea30e246ba8c5","disclosure":{"version":1,"level":"dd_summary","reason":"再現性・連続運転・顧客採用の判断条件。個別実験手順の具体値を含めず概要を開示。","dd":{"title":"顧客現場へ進む実証条件","summary":"ラボの取り込み実績から、顧客の排水ラインで使える証拠へ進むための試験計画案。","body_md":"### ラボから顧客現場へ進む条件\n\n10Lリアクターの処理、実排液での金属取り込み、pH変化等は研究者報告として把握している。初期濃度・最終濃度・処理時間・必要菌体量・反復・分析方法がそろった記録へ整理する。\n\n次の検証は、①顧客の排液を特定、②同条件の対照と反復、③連続運転・寿命・洗浄・停止復旧、④顧客の採用条件と検収。混合金属での遅延、油・塩分・共存成分、輸送後性能も判断に含める。原データは限定技術情報として別途照合する。","source_label":"技術台帳の研究者報告・事業化検討記録","check_reason":null},"reviewed_hash":"a058691f2cea935cb537d57ced9986726faf985ae33961b99b734ab5608eb0f6"}},{"entity":"topic","id":"ptt_sol_dd_supply","source_hash":"a2d6d8a6a0cd80bc4c3697cb8f2f18ee","disclosure":{"version":1,"level":"dd_summary","reason":"供給能力と品質・寿命・運用負担は事業判断に必要。培養配合と検査手順は限定管理。","dd":{"title":"供給・品質・現場運転の検証課題","summary":"供給する製品と運用の単位を定め、研究室の手順を出荷・現場保守へ移すための計画案。","body_md":"### 供給と現場運転の検証\n\n培養・出荷判定・包装・輸送・顧客投入・交換回収をつないだ製品単位を計画する。供給能力は槽の容量だけでなく、培養日数、菌体量、回収歩留まり、出荷合格率、輸送後性能で確認する。\n\n保存期限、ロット品質、カートリッジ寿命、洗浄作業、菌体漏出、故障時の代替、回収・廃棄は未確定。3ロット連続合格や顧客現場での再現は開発目標。培地配合、制御設定、検査・回収の詳細手順は通常DDの対象外。","source_label":"技術台帳の研究者報告・事業化検討記録","check_reason":null},"reviewed_hash":"6319b861ee75ad0aad00b654fd4cd33a5c9e13567082f5ae4c0bca83cfdc34ea"}},{"entity":"topic","id":"ptt_sol_dd_ip_use","source_hash":"b6dd04012c7968f4ade912b871614a1a","disclosure":{"version":1,"level":"dd_summary","reason":"投資対象が技術を利用できる条件を示す。未公開の具体的手順と個別交渉は含めない。","dd":{"title":"知財・ノウハウの利用条件と確認状況","summary":"出願の存在と、設立予定会社が事業で使える権利を分けて説明する。","body_md":"### 大学の技術を事業で使う条件\n\n知財一覧の出願・公開公報と、新会社の利用権を区別する。対象特許・菌株・ノウハウ、用途・地域・期間、独占性、委託製造、改良成果、対価、契約終了時の継続利用を協議する。公開公報の存在だけで、登録済み・有効・独占実施権取得済みとは扱わない。\n\n株の改変・選抜の未公開手順は核心ノウハウとして保持し、通常DDでは利用・引継ぎの条件と確認状況を示す。","source_label":"技術台帳の研究者報告・事業化検討記録","check_reason":null},"reviewed_hash":"b406aa54c32deb352780ef7ae50fbcbe7e74ee9d822bf41226b04ef870135d4e"}},{"entity":"topic","id":"ptt_sx_culture","source_hash":"800bde5a6fb113f7f7c166d6b76370f2","disclosure":{"version":1,"level":"core","reason":"原本には培養制御・光・気体・換算・改変情報が混在。供給能力に関わる要約行だけをDDへ残す。","dd":{"title":"菌体供給の能力と残る検証","summary":"培養時間・試作設備の容量・資源利用の予備報告。配合と制御設定は非開示。","body_md":null,"source_label":"技術台帳の研究者報告・事業化検討記録","check_reason":null},"reviewed_hash":"53d0e3c5fee486110ef3ffe46d4f8dc418d89a0bec575161a91d188dbc1c2fe1"}},{"entity":"topic","id":"ptt_sx_principle","source_hash":"d0e632f390bd86230f8151f114f3ccc7","disclosure":{"version":1,"level":"public","reason":"一般的な原理と製品構想の概要だけを公開情報とする。具体的な条件とノウハウはDD原稿へ転記しない。","dd":{"title":"技術の仕組み（概要）","summary":"培養と排液処理の工程、金属・色素・燃料の用途を区別。","body_md":"### 技術の概要\n\n光合成を行うシアノバクテリアを培養し、顧客の排液処理に利用する構想。培養と、排液に接触させる処理を別の工程として管理する。金属の液中濃度低下、菌体への取り込み、金属の抽出・精製はそれぞれ確認する。色素・金属・燃料は用途ごとに実証段階が異なる。\n\n未公開の培養・株改変・選抜の手順は通常DDに含めない。","source_label":"技術台帳の研究者報告・事業化検討記録","check_reason":null},"reviewed_hash":"11b8c5945a69cb160d1344443b738b57d8c4b0ec42aa6070034fb9422648aee7"}},{"entity":"topic","id":"ptt_sx_record","source_hash":"b9abcae2e33deb96f8a0f39a09e9f197","disclosure":{"version":1,"level":"restricted","reason":"装置の内部構造・株の改変・実験トラブルが混在。到達点と運転課題の概要だけをDDへ抜粋。","dd":{"title":"装置と実排液試験の到達点","summary":"報告日と試験日、研究者報告と原データ検証、ラボと顧客現場を区別。","body_md":null,"source_label":"技術台帳の研究者報告・事業化検討記録","check_reason":null},"reviewed_hash":"31b8d6dd4c403c0cdb5bf0e14a5f47de68dd7b0a66a24412594b2f27f3f9c3b3"}},{"entity":"topic","id":"ptt_sx_price","source_hash":"f989e1a8ca22416b3a943c9b1eda98e6","disclosure":{"version":1,"level":"restricted","reason":"過去時点の単価・原価。現在の採算判断はコスト試算と月次計画を正本とする。旧値を通常DDの現行値へ転用しない。","dd":null}},{"entity":"topic","id":"ptt_sx_elements","source_hash":"4920eeda509bf50d3488ed9d7fa6928d","disclosure":{"version":1,"level":"dd_summary","reason":"最初の用途を選ぶための確認状況。未確認の元素も残し、実験手順を省く。","dd":{"title":"物質ごとの到達段階","summary":"確認済み・試験中・未確認を分け、金属回収率や商用保証へ外挿しない。","body_md":null,"source_label":"技術台帳の研究者報告・事業化検討記録","check_reason":null},"reviewed_hash":"f8a64cc73db268baea681f7579dfe6fb4f8b4b0d25a7e1288794864c9b226491"}},{"entity":"topic","id":"ptt_sx_reactor","source_hash":"0d7a2d7a49209f0c8737768bfe41544d","disclosure":{"version":1,"level":"restricted","reason":"個別実験と旧試算の前提が混在。原データ・具体的な装置設定は限定管理。","dd":{"title":"処理性能とスケールアップの条件","summary":"取り込み量、処理速度、混合排液での限界。量産能力と回収・寿命は未実証。","body_md":null,"source_label":"技術台帳の研究者報告・事業化検討記録","check_reason":null},"reviewed_hash":"ab085b0766afa1d035bb01483663bfa080bc3f270e5002afdd02dbca75b4b8dd"}},{"entity":"topic","id":"ptt_sx_limits","source_hash":"8016ff45e7f439d5c073d1f6600eae1b","disclosure":{"version":1,"level":"dd_summary","reason":"事業判断を左右する適用限界を隠さない。株の操作や個別試験手順は非掲載。","dd":{"title":"適用限界と追加確認が必要な排液","summary":"塩分・薬剤・油・混合成分・低温等の制約。未知の閾値を示す。","body_md":null,"source_label":"技術台帳の研究者報告・事業化検討記録","check_reason":null},"reviewed_hash":"008ba76257405bf337fd79b9c5f3775cc2c199a3fbd55ff74a5e8b00278a427b"}},{"entity":"topic","id":"ptt_sx_preference","source_hash":"71ac9a1383d104534123509b94048cc5","disclosure":{"version":1,"level":"restricted","reason":"元素の選好と共存条件ごとの挙動は詳細技術検証。通常DDには混合で遅くなるという事業上の制約を性能欄へ集約。","dd":null}},{"entity":"topic","id":"ptt_sx_biofuel","source_hash":"be1a1b62391dea59002a21f083692271","disclosure":{"version":1,"level":"restricted","reason":"燃料化・出力の数値は事業判断に必要。抽出工程・溶媒の運用・個別株の比較は限定管理。","dd":{"title":"燃料の到達点と量産上の課題","summary":"ラボの分析値、設備出力の試算、量産と規格・原価で未確認の項目を区別。","body_md":null,"source_label":"技術台帳の研究者報告・事業化検討記録","check_reason":null},"reviewed_hash":"5f0ed5c8dd9991c18fd411251c2ed10716cabbf78e8c0ccf29c52444708fdb5e"}},{"entity":"topic","id":"ptt_sx_effluent_sources","source_hash":"d51cee912a25a144b7d6b25ece1709b6","disclosure":{"version":1,"level":"restricted","reason":"顧客別の水質・成分・採取位置・提供条件。匿名化とデータ開示条件の個別確認が必要。通常DDの技術ページへは収録しない。","dd":null}},{"entity":"topic","id":"ptt_sx_spec_sheet","source_hash":"638a0efeb85269706bfcaaccc8ada2cc","disclosure":{"version":1,"level":"restricted","reason":"性能と株・培養設定が混在する原本。投資判断に必要な行だけを抜粋する。","dd":{"title":"性能と適用範囲 — 事業判断のサマリー","summary":"性能の報告例、適用できない条件、未実証の範囲。試験ごとの設定は別管理。","body_md":null,"source_label":"技術台帳の研究者報告・事業化検討記録","check_reason":null},"reviewed_hash":"24f559ab5d9abcea39bec7e0c342e2f1701416bc6401cd361f549e173fdffb4b"}},{"entity":"topic","id":"ptt_sx_closed_law","source_hash":"a425020e5fd427e17e3a9b967ffaf066","disclosure":{"version":1,"level":"dd_summary","reason":"手続きの確認状況を概要で示す。適合・承認の取得済みを推測しない。","dd":{"title":"商用運用で確認する手続きと責任","summary":"輸送・使用・回収・廃棄の条件と、商用運用で必要な確認・責任分担。","body_md":"閉鎖系での使用は、装置に入れる時点だけでなく、保管・輸送・回収・廃棄までを含めて確認する。対象株、設備、運用主体を決めて、適用区分・必要な手続き・責任分担を確認する。現状は商用条件の確定前。個別の承認・適合を取得済みとは記載しない。","source_label":"技術台帳の研究者報告・事業化検討記録","check_reason":null},"reviewed_hash":"d8f9d8ea742de8d17f869b1d189ce43c2b08bfdeec5b410cf40982aa121a3dc3"}},{"entity":"topic","id":"ptt_sx_closed_overview","source_hash":"6bdcb1b9b1a244c4a5b330a22c19ae8d","disclosure":{"version":1,"level":"dd_summary","reason":"封じ込めと運用上の制約は事業判断に必要。未公開の株の詳細は説明しない。","dd":{"title":"強化株の使用条件と事業化の確認事項","summary":"対象株・設備・運用主体を定め、封じ込めと手続きの適用を確認する。","body_md":"### 事業化で確認する条件\n\n自然株と遺伝子組換え株を分け、使用・保管・輸送・回収・廃棄までを含む封じ込めと手続きの適用を確認する。分類、必要な確認、担当窓口、処理水と残渣の扱いは実証仕様と合わせて確定する。研究室での使用状態を、そのまま商用設備の適合確認済みと扱わない。\n\n具体的な株の改変内容・遺伝子・選抜条件は開示対象に含めない。","source_label":"技術台帳の研究者報告・事業化検討記録","check_reason":null},"reviewed_hash":"9d3296c9f7b03afb75bc8250313d0aa885c31a3e1fbd9c79b6a3f933a9c59a26"}},{"entity":"topic","id":"ptt_sx_closed_categories","source_hash":"5df691119e0473febf6a33a041fde977","disclosure":{"version":1,"level":"restricted","reason":"使用区分ごとの詳細要件。通常DDでは適用区分が未確定であることと事業上の制約を概要に示す。","dd":null}},{"entity":"topic","id":"ptt_sx_closed_gilsp","source_hash":"36af9f3e439b58e142485e84e924b207","disclosure":{"version":1,"level":"restricted","reason":"株・宿主・ベクター・挿入情報の詳細と使用区分の判断資料。通常DDの対象外。","dd":null}},{"entity":"topic","id":"ptt_sx_closed_reactor","source_hash":"0f5dd898978d9dc33a3843937bc3a382","disclosure":{"version":1,"level":"restricted","reason":"設備と不活化・封じ込め手順の詳細。事業化で必要な確認事項は概要に残す。","dd":null}},{"entity":"topic","id":"ptt_sx_closed_precedent","source_hash":"a783a5a70f188167982b5fddb56d4dea","disclosure":{"version":1,"level":"restricted","reason":"内部調査と未照合の先行事例。公表原本と時点を確認してから必要な説明へ採用する。","dd":null}},{"entity":"topic","id":"ptt_sx_closed_mechanism","source_hash":"107fa7513b83511efa42d23d9ccea411","disclosure":{"version":1,"level":"core","reason":"株の機能強化と取り込み機構の具体説明。通常DDでは一般的な取り込み・回収の構造だけを概要として示す。","dd":null}},{"entity":"topic","id":"ptt_sol_qa","source_hash":"3b149f55a05ae8a5da012bc440ae0aaa","disclosure":{"version":1,"level":"dd_summary","reason":"投資家向けの要約として必要。旧数値や実験手順をそのまま出さず、DD回答欄を明示する。","dd":{"title":"事業化の判断に必要な質問と答え","summary":"実績・量産・顧客・資金の現在地。過去の回答と現行計画を混同しない。","body_md":null,"source_label":"技術台帳の研究者報告・事業化検討記録","check_reason":null},"reviewed_hash":"8d7ff7f147989a9eaf9ddfd4e6b76333b9a337f29b718edb43c0835598c692ca"}},{"entity":"topic","id":"ptt_sx_valuables","source_hash":"689ee2a9aa4755b90f06ac2266851611","disclosure":{"version":1,"level":"dd_summary","reason":"事業上の可能性と未達を示す概要。抽出手順や未確認の収率を商用成果として出さない。","dd":{"title":"有価物の候補と実証段階","summary":"同定・収率・純度・販売品質が未確定の候補を、主ケースの収益と区別。","body_md":null,"source_label":"技術台帳の研究者報告・事業化検討記録","check_reason":null},"reviewed_hash":"82c1953fb02b2bebf1ce1618feb7bb9a6c40b4400b30f4ee2a22eb6c094c4006"}}]'::jsonb) AS x(id text,source_hash text,disclosure jsonb)), updated AS (UPDATE public.project_tech_topics r SET disclosure=x.disclosure FROM input x WHERE r.tech_topic_id=x.id AND r.project_id='p21' AND md5((to_jsonb(r)-'disclosure'-'created_by'-'updated_by'-'created_at'-'updated_at'-'sort_order')::text)=x.source_hash RETURNING r.tech_topic_id) SELECT count(*) INTO changed FROM updated;
 IF changed<>23 THEN RAISE EXCEPTION 'Tech disclosure snapshot changed: %/23',changed; END IF; END $amie$;
