losure=x.disclosure FROM input x WHERE r.tech_entry_id=x.id AND r.project_id='p21' AND md5((to_jsonb(r)-'disclosure'-'created_by'-'updated_by'-'created_at'-'updated_at'-'sort_order')::text)=x.source_hash RETURNING r.tech_entry_id) SELECT count(*) INTO changed FROM updated;
 IF changed<>248 THEN RAISE EXCEPTION 'Tech disclosure snapshot changed: %/248',changed; END IF; END $amie$;
COMMIT;
